const originalModal=modal,originalClose=close,originalRender=render,originalRunPage=pages.run;
const B=(label,action,param='',cls='')=>`<button class="btn ${cls}" data-v2="${action}" data-key="${esc(param)}">${label}</button>`;
const F=(label,id,value='',type='text')=>field(label,`<input class="input" id="${id}" type="${type}" value="${esc(value)}">`);
const fmt=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' UTC+08:00':'基线演示记录';
const titleOf=k=>assetGroups.flatMap(g=>g.types).find(x=>x[0]===k)?.[1]||k;
