const val=id=>document.getElementById(id)?.value?.trim()||'';
const dump=v=>`<pre class="code">${esc(JSON.stringify(v,null,2))}</pre>`;
function init(){
 core=C.create(S,assets);for(const t of S.evalTasks){t.assemblyMode=t.assemblyMode||(t.template?'SUITE':'DIRECT');t.contentMode=t.contentMode||(t.type==='Agent'?'CASE':'DATASET');t.executionScope=t.executionScope||'DEMO_REPLAY_ONLY';if(t.template&&SCENARIO_FIXTURES[t.template]&&!t.objectProof)t.objectProof={kind:'fixture',ref:t.template+'@'+SCENARIO_FIXTURES[t.template].version};}(S.customAssets||[]).forEach(a=>core.adopt(a));
 S.customAssets=core.list().filter(a=>!assets.some(x=>C.key(x)===C.key(a)));
 S.v2.views=S.v2.views||{};S.v2.demo=S.v2.demo||{list:'ready',result:'recorded'};
 if(!core.db.works.length){let a=core.adopt({id:'AS-CW-028',version:'r1',kind:'case',type:'评测用例',name:'用户拒绝后停止执行',targets:['Agent'],owner:'林工',source:'CW-028 / 合成宠物服务样例',caseSpec:CaseContracts.legacySpec(CaseContracts.example('pet'),CaseContracts.catalog(S))});a.content=CaseAuthoring.content(a.caseSpec);a.config={scene:'pet'};core.db.works.push({id:'CW-028',title:'用户拒绝后停止执行用例沉淀',status:'进行中',assetKey:C.key(a),messages:[],handoff:{state:'尚未提交',assignee:'expert'}});}
}
