const oldNav=renderNav;
// Inbox is a global utility, not a primary work area.
for(const g of navGroups)g.items=g.items.filter(([id])=>!['new','design'].includes(id));
renderNav=function(){oldNav();document.querySelector('.navsub')?.remove();document.querySelectorAll('#nav .count').forEach(x=>x.remove());const inbox=document.querySelector('#nav [data-param="inbox"]');if(inbox&&openTodos().length)inbox.insertAdjacentHTML('beforeend','<span class="count">'+openTodos().length+'</span>');};
render=function(){core.migrateRuns();originalRender();if(S.route==='case-builder'&&S.v2.editContext){const task=S.evalTasks.find(t=>t.id===S.v2.editContext.taskId);document.querySelector('#main').insertAdjacentHTML('afterbegin','<div class="v2-analysis">正在为任务 '+esc(task?.name||S.v2.editContext.taskId)+' 补齐依赖。'+B('保存并返回任务','save-case-return','','sm')+'</div>');}document.querySelector('.footer-note').textContent='UI/UX · 2026-10-29 正常自动收尾版 · 合成数据 / 开发回放 · 北京时间 UTC+08:00';if(!document.getElementById('v2-role-banner'))document.querySelector('.shell').insertAdjacentHTML('afterbegin','<div id="v2-role-banner" class="v2-role-banner"></div>');document.getElementById('v2-role-banner').innerHTML='<span>交互原型 · 正常自动收尾 / 合成回放　/　当前以 <b>'+roleNames[S.role]+'</b> 演示</span><div>'+B('演示控制','demo','','ghost sm')+B('术语表','glossary','','ghost sm')+'</div>';document.querySelectorAll('button:disabled').forEach(b=>{if(!b.title)b.title='当前前置条件未满足，请查看相关检查结果。';});document.querySelectorAll('.modal select').forEach(x=>x.setAttribute('aria-label',x.getAttribute('aria-label')||x.id||'配置选择'));commit();};
const intercept={'new-requirement':'new',template:'template',inbox:'inbox','asset-detail':'asset','df-dep-edit':'edit-dep','df-open':'task','asset-new':'new-asset','asset-create':'new-asset','aa-save':'save-asset','aa-edit':'edit-asset','aa-check':'validate','df-independent-edit':'edit-asset','df-independent-validate':'validate','df-independent-expert':'approve','df-independent-publish':'approve','asset-derive':'revise','df-from-asset':'from-asset','reset-demo':'demo','reset-confirm':'reset-confirm','df-freeze':'freeze','df-run':'run','df-approve-assets':'inbox','df-approve-save':'inbox','df-confirm':'confirm-task','df-confirm-save':'confirm-task-save'};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v2]');if(b){e.preventDefault();e.stopImmediatePropagation();handle(b.dataset.v2,b.dataset.key||'',b);return;}const old=e.target.closest('[data-action]');if(old?.closest('#case-design-review'))return;if(old?.dataset.action==='v2-inbox-tab'){e.stopImmediatePropagation();S.v2.inboxTab=old.dataset.param;show();return;}if(old&&intercept[old.dataset.action]){e.stopImmediatePropagation();handle(intercept[old.dataset.action],old.dataset.param||'',old);return;}if(e.target.dataset.overlay){e.stopImmediatePropagation();if(!document.querySelector('.modal input,.modal textarea,.modal select'))close();}},true);
document.addEventListener('input',e=>{if(e.target.closest('.modal')&&!e.target.closest('#global-search'))modalDirty=true;});
document.addEventListener('change',e=>{if(e.target.dataset.assetDraft==='memberKind'){assetEditorRead();assetEditorRender();modalDirty=true;}});
document.addEventListener('change',e=>{if(e.target.id==='v2-asset-type'){S.assetType=e.target.value;view('assets').page=1;view('assets').selected=[];show();}if(e.target.dataset.listQuery){const v=view(e.target.dataset.listQuery);v.query=e.target.value;v.page=1;show();}if(e.target.dataset.listFilter){const v=view(e.target.dataset.listFilter);v.filter=e.target.value;v.page=1;show();}if(e.target.dataset.selectList){const v=view(e.target.dataset.selectList);v.selected=e.target.checked?[...new Set([...v.selected,e.target.value])]:v.selected.filter(x=>x!==e.target.value);show();}if(e.target.dataset.selectPage){const n=e.target.dataset.selectPage;document.querySelectorAll('[data-select-list="'+n+'"]').forEach(cb=>{cb.checked=e.target.checked;const v=view(n);v.selected=e.target.checked?[...new Set([...v.selected,cb.value])]:v.selected.filter(x=>x!==cb.value);});show();}});
const priorSearch=searchResults;searchResults=function(query){let extra=[...S.evalTasks.map(t=>({name:t.name,id:t.id,action:'task',kind:'任务'})),...S.runs.map(r=>({name:r.name,id:r.id,action:'run-open',kind:'运行'}))].filter(x=>(x.name+x.id).toLowerCase().includes(query.toLowerCase()));return '<h3>页面 / 资产</h3>'+priorSearch(query)+'<h3>任务 / 运行</h3>'+extra.map(x=>B(x.kind+' · '+esc(x.name)+' · '+x.id,x.action,x.id,'v2-search-result')).join('');};
document.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp'].includes(e.key)||!document.querySelector('#global-search'))return;const options=[...document.querySelectorAll('#search-results button')];if(!options.length)return;const i=options.indexOf(document.activeElement),next=e.key==='ArrowDown'?(i+1)%options.length:(i-1+options.length)%options.length;e.preventDefault();options[next].focus();});
